public TreeNode<T> rotateRight(TreeNode<T> node) {
    // Create a new parent node
    TreeNode<T> newParent = new TreeNode<T>(node.data);

    // Set the new parent's left child to the node's right child
    newParent.left = node.right;

    // Set the node's right child to the new parent
    node.right = newParent;

    // Return the new parent
    return newParent;
}

public TreeNode<T> rotateRight(TreeNode<T> node) {
    // create a new parent node for the old right child
    TreeNode<T> oldRight = node.right;
    TreeNode<T> newParent = new TreeNode<>(oldRight.data);
    newParent.left = oldRight.left;

    // reconnect the parent node to the old parent
    oldRight.left = node;
    node.right = oldRight;

    // update the parent pointers to the new nodes
    newParent.parent = node.parent;
    node.parent = newParent;
    oldRight.parent = newParent;

    return newParent;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Save the current left child and its right child
    TreeNode<T> leftChild = node.left;
    TreeNode<T> rightChild = leftChild.right;

    // Rotate the current node to the left
    node.left = rightChild;

    // Update the parent of the right child
    if (rightChild != null) {
        rightChild.parent = node;
    }

    // Update the parent of the left child
    leftChild.parent = node.parent;

    // If the parent is null, the current node is the root
    if (node.parent == null) {
        return leftChild;
    }

    // If the parent is not null, update the left child of the parent
    if (node.parent.left == node) {
        node.parent.left = leftChild;
    } else {
        node.parent.right = leftChild;
    }

    return node;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Get the left child of the node
    TreeNode<T> leftChild = node.left;

    // Set the parent of the left child to the right child of the node
    leftChild.parent = node.right;

    // Set the right child of the node to the left child of the node
    node.right = leftChild;

    // Replace the node with its right child
    return node.right;
}

