public static void addToClassPath(Vector<URL> cpV, String dir) {
    File dirFile = new File(dir);
    if (!dirFile.exists() || dirFile.isFile()) {
        throw new IllegalArgumentException("Invalid directory: " + dir);
    }
    if (!dirFile.isDirectory()) {
        throw new IllegalArgumentException("File is not a directory: " + dir);
    }
    File[] jarFiles = dirFile.listFiles((file) -> file.getName().endsWith(".jar"));
    for (File jarFile : jarFiles) {
        URL jarUrl;
        try {
            jarUrl = jarFile.toURI().toURL();
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Error converting file to URL: " + jarFile.getName());
        }
        cpV.add(jarUrl);
    }
}

private static void addToClassPath(Vector<URL> cpV, String dir) throws MalformedURLException {
    // Use the dir parameter to construct a File object
    File dirFile = new File(dir);

    // If the file is not a directory, throw an exception
    if (!dirFile.isDirectory()) {
        throw new IllegalArgumentException("The input dir must be a directory");
    }

    // Use the File#listFiles method to get a list of files in the directory
    File[] files = dirFile.listFiles();

    // Iterate over the list of files and add each one to the classpath
    for (File file : files) {
        // If the file is a JAR file, add it to the classpath
        if (file.getName().endsWith(".jar")) {
            URL jarUrl = file.toURI().toURL();
            cpV.add(jarUrl);
        }
    }
}

