public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // create a new graph that is isomorphic to the input graph
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>(graph);

    // for each vertex in the input graph, create a mapping that maps it to itself
    for (V vertex : graph.getVertices()) {
        mapping.add(vertex, vertex);
    }

    return mapping;
}

