public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type actualTypeArgument = actualTypeArguments[i];
        if (actualTypeArgument instanceof Class<?>) {
            resolvedArguments[i] = (Class<?>) actualTypeArgument;
            continue;
        }
        if (actualTypeArgument instanceof ParameterizedType) {
            // Recursively resolve arguments for ParameterizedType
            resolvedArguments[i] = resolveArguments(actualTypeArgument, targetType);
        }
    }
    return resolvedArguments;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    if (actualTypeArguments == null || actualTypeArguments.length == 0) {
        return null;
    }
    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type arg = actualTypeArguments[i];
        if (arg instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) arg;
            ResolvableType resolvedType = ResolvableType.forType(typeVariable, targetType);
            resolvedArguments[i] = resolvedType.resolve();
        } else if (arg instanceof Class) {
            resolvedArguments[i] = (Class<?>) arg;
        } else if (arg instanceof GenericArrayType) {
            GenericArrayType genericArrayType = (GenericArrayType) arg;
            resolvedArguments[i] = Array.newInstance(resolveArguments(genericArrayType.getGenericComponentType(), targetType), 0).getClass();
        } else if (arg instanceof ParameterizedType) {
            resolvedArguments[i] = resolveArguments((ParameterizedType) arg, targetType);
        } else {
            throw new IllegalStateException("Unexpected type: " + arg);
        }
    }
    return resolvedArguments;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType){
     if(!(genericType instanceof ParameterizedType)){
         return null;
     }
     ParameterizedType parameterizedType = (ParameterizedType) genericType;
     Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
     Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
     for(int i = 0; i < actualTypeArguments.length; i++){
         Type actualTypeArgument = actualTypeArguments[i];
         if(actualTypeArgument instanceof Class){
             resolvedArguments[i] = (Class<?>) actualTypeArgument;
         } else if(actualTypeArgument instanceof TypeVariable){
             TypeVariable typeVariable = (TypeVariable) actualTypeArgument;
             String typeVariableName = typeVariable.getName();
             Class<?> typeVariableClass = targetType.getDeclaredField(typeVariableName).getAnnotation(QueryParam.class).value();
             resolvedArguments[i] = typeVariableClass;
         } else{
             throw new RuntimeException("Failed to resolve argument type for generic type " + genericType + " and target type " + targetType);
         }
     }
     return resolvedArguments;
 }

