    if (systemName.equals("Windows 2000")) {
        directory = new File(homeDirectory + "\\Documents and Settings\\" + directoryName);
    } else {
        // Create the directory wherever the user.home variable points on all other platforms
        directory = new File(homeDirectory + "\\" + directoryName);
    }

    // Create the directory if it does not already exist
    if (!directory.exists()) {
        directory.mkdirs();
    }

    return true;
}

