protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long endTime = Math.min(end, start + FETCH_DATA_DURATION);
    while (start < end) {
        timeRanges.add(new TimeRange(start, endTime));
        start = endTime + FETCH_DATA_DURATION;
        endTime = Math.min(end, start + FETCH_DATA_DURATION);
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    long fetchDataDuration = FETCH_DATA_DURATION;
    long minRangeSize = Math.min(fetchDataDuration, end - start);

    for (long i = start; i < end; i += minRangeSize) {
        long rangeStart = i;
        long rangeEnd = i + minRangeSize;

        if (rangeEnd > end) {
            rangeEnd = end;
        }

        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long startTime = start;
    while (startTime < end - FETCH_DATA_DURATION) {
        long endTime = Math.min(startTime + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(startTime, endTime));
        startTime = endTime;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the maximum start time that is less than or equal to FETCH_DATA_DURATION
    long maxStart = Math.max(start, 0);
    maxStart = Math.min(maxStart, FETCH_DATA_DURATION);

    // Calculate the maximum end time that is less than or equal to FETCH_DATA_DURATION
    long maxEnd = Math.min(end, FETCH_DATA_DURATION);

    // Iterate from the maximum start time to the maximum end time
    for (long i = maxStart; i <= maxEnd; i++) {
        long startTime = i;
        long endTime = Math.min(i + FETCH_DATA_DURATION, maxEnd);
        timeRanges.add(new TimeRange(startTime, endTime));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return timeRanges;
}

