static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket / 1000000 * 1000000 + (timeBucket - timeBucket / 1000000 * 1000000) * dayStep / 100 + dayStep / 100 * 1000000;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % (long) dayStep) + 1;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the year and month from the time bucket
    int year = (int) ((timeBucket / 10000000000) % 10000);
    int month = (int) ((timeBucket / 10000000) % 100);

    // Calculate the day of the month from the time bucket
    int day = (int) (timeBucket % 100);

    // Calculate the new day of the month based on the day step
    int newDay = day - (day % dayStep);

    // Re-format the time bucket based on the new day of the month
    return year * 10000000000 + month * 10000000 + newDay * 100 + day;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % dayStep);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
        Date date = new Date(timeBucket);
        date.setDate(date.getDate() - (date.getDate() % dayStep));
        return date.getTime();
    }

public static int computeUTF8Size(String str, int index, int len) {
    int size = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c >= 0 && c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            if (Character.isLowSurrogate(str.charAt(i))) {
                size += 4;
            } else {
                throw new IllegalArgumentException("Invalid low surrogate");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            char low = str.charAt(i);
            if (!Character.isLowSurrogate(low)) {
                throw new IllegalArgumentException("illegal surrogate");
            }
            size += 4;
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len) {
    int byteCount = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            byteCount++;
        } else if (c < 0x800) {
            byteCount += 2;
        } else if (c < 0xd800 || c > 0xdfff) {
            byteCount += 3;
        } else {
            byteCount += 4;
        }
    }
    return byteCount;
}

