LinkedBuffer writeUTF8(str, session, lb) {
    // Write the length of the string as a 16-bit integer
    lb.writeShort(str.length());

    // Iterate over the characters in the string and convert them to UTF-8
    for (int i = 0; i < str.length(); i++) {
        // Get the next character in the string
        char c = str.get(i);

        // Special case some common characters for efficiency
        if (c == '\\n') {
            // Write a newline character (0x0A)
            lb.writeByte(0x0A);
        } else if (c == '\\r') {
            // Write a carriage return character (0x0D)
            lb.writeByte(0x0D);
        } else if (c >= '\\u0001' && c <= '\\u007F') {
            // Write the character directly using their ASCII value
            lb.writeByte(c);
        } else {
            // Write the character using UTF-8 encoding
            lb.writeByte((c >>> 6) | 0xC0);
            lb.writeByte((c & 0x3F) | 0x80);
        }
    }

    // Return the modified LinkedBuffer
    return lb;
}

void writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    for (int i = 0; i < str.length(); i++) {
        final char c = str.charAt(i);
        if (c >= 0x0001 && c <= 0x007F) {
            lb.append((byte) c);
        } else if (c > 0x07FF) {
            lb.append((byte) (0xE0 | c >> 12 & 0x0F));
            lb.append((byte) (0x80 | c >> 6 & 0x3F));
            lb.append((byte) (0x80 | c & 0x3F));
        } else {
            lb.append((byte) (0xC0 | c >> 6));
            lb.append((byte) (0x80 | c & 0x3F));
        }
    }
}

