public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value != null) {
        value = value.replaceAll("\\$\\{([^}]*)\\}", matches -> {
            String varName = matches.group(1);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                return varValue;
            }
            return "";
        });
    }
    return value;
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value != null) {
        Matcher m = VAR_PATTERN.matcher(value);
        while (m.find()) {
            String varName = m.group(1);
            String varValue = props.getProperty(varName);
            if (varValue == null) {
                varValue = "";
            }
            value = value.replace(m.group(), varValue);
        }
    }
    return value;
}

