}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path.isEmpty()) {
        return pathSegments;
    }
    boolean startsWithSlash = path.charAt(0) == '/';
    int start = startsWithSlash ? 1 : 0;
    int end;
    for (int i = start; i < path.length(); i = end + 1) {
        end = path.indexOf('/', i);
        if (end == -1) {
            end = path.length();
        }
        String segment = path.substring(i, end);
        if (decode) {
            segment = URLDecoder.decode(segment, "UTF-8");
        }
        pathSegments.add(new PathSegmentImpl(segment));
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Initialize the list to store the path segments
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Get the path component of the URI
    String path = u.getPath();

    // Split the path into individual segments using '/' as a delimiter
    String[] segments = path.split("/");

    // Add each segment to the list, with the leading '/' removed if necessary
    for (String segment : segments) {
      if (decode) {
        segment = decodeURIComponent(segment);
      }
      pathSegments.add(new PathSegmentImpl(segment, encodeUriComponent(segment)));
    }

    return pathSegments;
  }

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();

    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    for (String segment : path.split("/")) {
        segments.add(new PathSegmentImpl(decode ? UriUtils.decode(segment, "UTF-8") : segment));
    }

    return segments;
}

