private void pop(final String descriptor) {
if (descriptor.endsWith(")V")) { // Method descriptor
final String methodName = descriptor.substring(1, descriptor.indexOf('('));
final String argumentTypes = descriptor.substring(descriptor.indexOf('(') + 1, descriptor.lastIndexOf(')'));
// Pop argument types from output frame stack
for (int i = 0; i < argumentTypes.length(); i++) {
final Type argumentType = Type.getType(argumentTypes.charAt(i) + "");
pop(argumentType);
}
// Call method
final int methodIndex = getMethodIndex(methodName, argumentTypes);
call(methodIndex);
} else { // Type descriptor
final Type type = Type.getType(descriptor);
pop(type);
}
}

private void pop(String descriptor) {
    // If the descriptor is a primitive type, popping it will have no effect.
    if (descriptor.startsWith("B")) {
        outputFrame.popBoolean();
    } else if (descriptor.startsWith("C")) {
        outputFrame.popChar();
    } else if (descriptor.startsWith("D")) {
        outputFrame.popDouble();
    } else if (descriptor.startsWith("F")) {
        outputFrame.popFloat();
    } else if (descriptor.startsWith("I")) {
        outputFrame.popInt();
    } else if (descriptor.startsWith("J")) {
        outputFrame.popLong();
    } else if (descriptor.startsWith("L")) {
        // If the descriptor is a reference type, pop the corresponding number of reference types from the output frame stack.
        int numReferenceTypes = descriptor.length() - 1; // Subtract 1 for the initial "L" character.
        for (int i = 0; i < numReferenceTypes; i++) {
            outputFrame.popReference();
        }
    }
}

private void pop(String descriptor) {
    // Check if the descriptor corresponds to a field or a method
    if (descriptor.startsWith("(")) {
        // If the descriptor corresponds to a method, pop the argument types
        int argumentCount = Type.getArgumentTypes(descriptor).length;
        for (int i = 0; i < argumentCount; i++) {
            Frame.this.pop();
        }
    } else {
        // Otherwise, pop a single abstract type
        Frame.this.pop();
    }
}

private void pop(String descriptor) {
    switch (descriptor.charAt(0)) {
        case 'V':
            // do nothing
            break;
        case 'Z':
            pop();
            break;
        case 'B':
        case 'C':
        case 'S':
        case 'I':
            pop();
            break;
        case 'J':
        case 'F':
        case 'D':
            pop();
            pop();
            break;
        case 'L':
        case '[':
            // popping an array should pop its elements
            pop();
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

private void pop(String descriptor) {
    if (descriptor.equals("()V")) {
        // Do nothing
    } else if (descriptor.equals("()Ljava/lang/Object;")) {
        objectStack.pop();
    } else if (descriptor.equals("([Ljava/lang/Object;)V")) {
        objectStack.pop();
    } else if (descriptor.equals("([I)V")) {
        intStack.pop();
    } else if (descriptor.equals("([D)V")) {
        doubleStack.pop();
    } else if (descriptor.equals("([J)V")) {
        longStack.pop();
    } else if (descriptor.equals("([F)V")) {
        floatStack.pop();
    } else if (descriptor.equals("([Z)V")) {
        booleanStack.pop();
    } else {
        throw new RuntimeException("Invalid descriptor: " + descriptor);
    }
}

