public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    double x = box.getX() + box.getWidth() / 2;
    Box2D firstBox = new Box2D(box.getX(), box.getY(), x - box.getX(), box.getHeight());
    Box2D secondBox = new Box2D(x, box.getY(), box.getX() + box.getWidth() - x, box.getHeight());
    return new Pair<>(firstBox, secondBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    Point2D center = box.getCenter();
    double halfWidth = box.getWidth() * 0.5;
    Box2D box1 = new Box2D(center.getX() - halfWidth, center.getY() - halfWidth, halfWidth, halfWidth);
    Box2D box2 = new Box2D(center.getX() + halfWidth, center.getY() - halfWidth, halfWidth, halfWidth);
    return new Pair<>(box1, box2);
}

