        Box2D box1 = new Box2D(box.getMin().getX(), box.getMin().getY(), halfSizeX, box.getHeight());
        Box2D box2 = new Box2D(box.getMin().getX() + halfSizeX, box.getMin().getY(), halfSizeX, box.getHeight());

        // Return the two resulting boxes
        return new Pair<>(box1, box2);
    }

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
return new Pair(box.divide2By(2, 0), box.divide2By(2, 1));
