public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the middle point of the box along the x-axis
    double middleX = box.getX() + box.getWidth() / 2;

    // Create two new boxes with different x coordinates
    Box2D leftBox = new Box2D(box.getX(), box.getY(), middleX - box.getX(), box.getHeight());
    Box2D rightBox = new Box2D(middleX, box.getY(), box.getWidth() - (middleX - box.getX()), box.getHeight());

    return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

