    // Check if all required fields are present
    for (String field : fields.getRequiredFields()) {
        if (!properties.containsKey(field)) {
            return false;
        }
    }

    // Check if all optional fields are in the properties
    for (String field : fields.getOptionalFields()) {
        if (!properties.containsKey(field)) {
            // If an optional field is missing, we consider the input valid
            return true;
        }
    }

    // If we reach this point, all required fields are present and all optional fields are in the properties
    return true;
}

