public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity >= 1000) {
        // Use the more precise algorithm for large capacities
        long n = (long) desiredCapacity;
        n |= n >>> 1;
        n |= n >>> 2;
        n |= n >>> 4;
        n |= n >>> 8;
        n |= n >>> 16;
        return (int) Math.min(Integer.MAX_VALUE, n + 1);
    } else {
        // Use the simple algorithm for small capacities
        for (int i = desiredCapacity;; i++) {
            if (isPrime(i)) {
                return i;
            }
        }
    }
}

public static int nextPrime(int desiredCapacity) {
  // check if desiredCapacity is already prime
  if (isPrime(desiredCapacity)) {
    return desiredCapacity;
  }

  // find the closest prime number that is >= desiredCapacity
  int currentPrime = 2;
  while (currentPrime < desiredCapacity) {
    currentPrime = currentPrime + 1;
    if (isPrime(currentPrime)) {
      return currentPrime;
    }
  }

  // if the desiredCapacity is very large, use a prime number very close to it
  if (desiredCapacity >= 1000) {
    currentPrime = (int) Math.floor(desiredCapacity * 1.1);
    while (!isPrime(currentPrime)) {
      currentPrime--;
    }
    return currentPrime;
  }

  // otherwise, use the closest prime number
  currentPrime = (int) Math.ceil(desiredCapacity / 2) * 2 + 1;
  while (!isPrime(currentPrime)) {
    currentPrime++;
  }
  return currentPrime;
}

