private static int digitValue(char c) {
    if ('0' <= c && c <= '9') {
        return c - '0';
    } else if ('a' <= c && c <= 'z') {
        return c - 'a' + 10;
    } else if ('A' <= c && c <= 'Z') {
        return c - 'A' + 10;
    } else {
        return -1;
    }
}

