    } else if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    return -1;
}

public static int digitValue(char c) {
        // Check if the character is a digit
        if (c >= '0' && c <= '9') {
            // If it's a digit, return its numeric value
            return c - '0';
        } else if (c >= 'a' && c <= 'z') {
            // If it's a lowercase letter, return its value in base 36
            return c - 'a' + 10;
        } else if (c >= 'A' && c <= 'Z') {
            // If it's an uppercase letter, return its value in base 36
            return c - 'A' + 10;
        }
        // If the character is not a digit or letter, return -1
        return -1;
    }

