public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder builder = new StringBuilder(str.length());
    int pos = 0;
    while (pos < str.length()) {
        char c = str.charAt(pos);
        if (c == '\\') {
            pos++;
            if (pos < str.length()) {
                c = str.charAt(pos);
                switch (c) {
                    case 'b':
                        builder.append('\b');
                        break;
                    case 't':
                        builder.append('\t');
                        break;
                    case 'n':
                        builder.append('\n');
                        break;
                    case 'f':
                        builder.append('\f');
                        break;
                    case 'r':
                        builder.append('\r');
                        break;
                    case '\\':
                    case '\'':
                    case '\"':
                    case '/':
                        builder.append(c);
                }
                pos++;
            }
        } else {
            builder.append(c);
            pos++;
        }
    }
    return builder.toString();
}

public static String unescapeJava(String str) throws Exception {
    // Initialize a new string builder to hold the unescaped string
    StringBuilder sb = new StringBuilder();

    // Loop through each character in the input string
    for (int i = 0; i < str.length(); i++) {
        // Check if the current character is a backslash
        if (str.charAt(i) == '\\') {
            // If the next character is a '\' or 'n', add the corresponding escape sequence
            if (i + 1 < str.length() && (str.charAt(i + 1) == '\\' || str.charAt(i + 1) == 'n')) {
                sb.append(str.charAt(i + 1));
                i++;
            // Otherwise, add the backslash to the string builder
            } else {
                sb.append('\\');
            }
        // Add the current character to the string builder
        } else {
            sb.append(str.charAt(i));
        }
    }

    // Return the unescaped string
    return sb.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            char next = (i == str.length() - 1) ? '\0' : str.charAt(i + 1);
            switch (next) {
                case 'n':
                    result.append('\n');
                    i++;
                    break;
                case 'r':
                    result.append('\r');
                    i++;
                    break;
                case 't':
                    result.append('\t');
                    i++;
                    break;
                case 'b':
                    result.append('\b');
                    i++;
                    break;
                case 'f':
                    result.append('\f');
                    i++;
                    break;
                case '\\':
                    result.append('\\');
                    i++;
                    break;
                case '\'':
                    result.append('\'');
                    i++;
                    break;
                case '\"':
                    result.append('\"');
                    i++;
                    break;
                case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9':
                    int octal = next - '0';
                    if (i < str.length() - 2) {
                        char next2 = str.charAt(i + 2);
                        if (next2 >= '0' && next2 <= '7') {
                            octal = (octal << 3) + next2 - '0';
                            i += 2;
                            if (i < str.length() - 2) {
                                char next3 = str.charAt(i + 2);
                                if (next3 >= '0' && next3 <= '7') {
                                    octal = (octal << 3) + next3 - '0';
                                    i++;
                                }
                            }
                        }
                    }
                    result.append((char) octal);
                    i++;
                    break;
                default:
                    throw new Exception("Illegal text after escape character.");
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    boolean hasEscapedChar = false;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && hasEscapedChar) {
            hasEscapedChar = false;
            switch (c) {
                case 'n':
                    c = '\n';
                    break;
                case 't':
                    c = '\t';
                    break;
                case 'b':
                    c = '\b';
                    break;
                case 'f':
                    c = '\f';
                    break;
                case 'r':
                    c = '\r';
                    break;
                case '\\':
                    c = '\\';
                    break;
                case '\'':
                    c = '\'';
                    break;
                case '\"':
                    c = '\"';
                    break;
                default:
                    throw new Exception("Invalid escape sequence: " + c);
            }
        } else {
            hasEscapedChar = c == '\\';
        }

        result.append(c);
    }

    return result.toString();
}

public static String unescapeJava(String str) throws Exception {
