int i = 0;
while (i < len) {
char c = str.charAt(i);
if (c == '\\') {
i++;
c = str.charAt(i);
if (c == 'n') {
builder.append('\n');
} else if (c == 't') {
builder.append('\t');
} else if (c == '\\') {
builder.append('\\');
} else if (c == '\'') {
builder.append('\'');
} else if (c == '\"') {
builder.append('\"');
} else if (c == 'b') {
builder.append('\b');
} else if (c == 'f') {
