} else if (c == 'r') {
builder.append('\r');
} else if (c == 'u') {
// handle unicode character
i++;
String hex = str.substring(i, i + 4);
builder.append((char) Integer.parseInt(hex, 16));
i += 4;
} else {
builder.append(c);
}
} else {
builder.append(c);
}
i++;
}
return builder.toString();
} else {
return str;
}
}

