        "UTF-32", "java.nio.charset.StandardCharsets.UTF_32",
        "US-ASCII", "java.nio.charset.StandardCharsets.US_ASCII",
        "ISO-8859-1", "java.nio.charset.StandardCharsets.ISO_8859_1"
    );

    // Check if MIME standard name is in the map
    if (javaCharsetMap.containsKey(charset)) {
