public static void removeUnusedNodes(Category root) {
    if (root == null) {
        return;
    }

    // Remove any inactive nodes
    for (Category category : root.getChildren()) {
        if (category.isInactive()) {
            root.removeChild(category);
            removeUnusedNodes(category);
        }
    }
}

protected int removeUnusedNodes() {
    int count = 0;
    for (Category category : categories.values()) {
        if (!category.isActive()) {
            categories.remove(category.getName());
            count++;
        }
    }
    return count;
}

protected int removeUnusedNodes() {
    // Initialize a list to store the inactive nodes
    List<Category> inactiveNodes = new ArrayList<>();
    // Iterate over the Category tree to find the inactive nodes
    for (Category category : categories) {
        if (category.getActive() == false) {
            inactiveNodes.add(category);
        }
    }
    // Iterate over the inactive nodes and remove them from the tree
    for (Category inactiveNode : inactiveNodes) {
        categories.remove(inactiveNode);
    }
    // Return the number of inactive nodes removed from the tree
    return inactiveNodes.size();
}

public int removeUnusedNodes() {
    // Traverse the tree and mark all used nodes
    traverseTree(root, new TreeNodeVisitor() {
        @Override
        public void visit(TreeNode node) {
            node.setUsed(true);
        }
    });

    // Traverse the tree again and remove unused nodes
    traverseTree(root, new TreeNodeVisitor() {
        @Override
        public void visit(TreeNode node) {
            if (!node.isUsed()) {
                node.getParent().removeChild(node);
                node.detachFromParent();
            }
        }
    });

    return root.getChildCount();
}

public int removeUnusedNodes() {
    // Initialize a list to store the inactive nodes
    List<Category> inactiveNodes = new ArrayList<>();

    // Iterate over the nodes in the Category tree
    for (Category node : getAllNodes()) {
        // Check if the node is inactive
        if (!node.isActive()) {
            // Add the inactive node to the list
            inactiveNodes.add(node);
        }
    }

    // Iterate over the inactive nodes and remove them from the tree
    for (Category node : inactiveNodes) {
        removeNode(node.getId());
    }

    // Return the number of inactive nodes removed
    return inactiveNodes.size();
}

