    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    circulator.find(n -> predicate.test(n) || n == stop);

    if (circulator.curr() == stop) {
        return circulator;
    }

    // If we reach this point, it means we found a node that satisfies the predicate but it is not the stop node.
    // We need to find the next node on the outer face of the component.
    circulator.next();
    if (circulator.curr() == stop) {
        return circulator;
    }

    // If we reach this point, it means we did not find any node on the outer face of the component that satisfies the predicate.
    // We return null to indicate that no such node exists.
    return null;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // find the first node on the outer face that satisfies the predicate
    Node curr = start;
    do {
        curr = curr.getNeighbor(dir);
    } while (!predicate.test(curr) && curr != stop);

    // if a node satisfying the predicate was not found, return a circulator to the stop node
    if (curr == stop) {
        return new OuterFaceCirculator(stop);
    }

    // create a circulator to the first node that satisfies the predicate
    OuterFaceCirculator cir = new OuterFaceCirculator(curr);

    // find the next node on the outer face that does not satisfy the predicate
    Node next = curr.getNeighbor((dir + 2) % 4);
    while (next != stop && predicate.test(next)) {
        next = next.getNeighbor((dir + 2) % 4);
    }

    // if the next node was the stop node, return the circulator to the first node that satisfies the predicate
    if (next == stop) {
        return cir;
    }

    // return a circulator that goes from the first node that satisfies the predicate to the next node that does not satisfy the predicate
    return new OuterFaceCirculator(curr, next);
}

