public static void register(Object value) {
    // Register the object in the internal map
    // To avoid infinite loops, we need to check if the object
    // is already registered. We can use the Object.hashCode() method
    // to get a unique hash code for the object. If the hash code is
    // already present in the map, we know that the object has already
    // been registered and we can skip the registration process.
    if (!reflectionMap.containsKey(value.hashCode())) {
        // If the object is not registered, we need to add it to
        // the map and then recursively register its fields.
        reflectionMap.put(value.hashCode(), value);
        // Use the Object.getClass() method to get the class of the object
        // and then get its declared fields using the Class.getDeclaredFields() method.
        Field[] fields = value.getClass().getDeclaredFields();
        // Iterate over the array of fields and register each one.
        for (Field field : fields) {
            try {
                // Use the Field.get() method to get the value of the field.
                // Use the Field.getName() method to get the name of the field.
                register(field.getName(), field.get(value));
            } catch (Exception ex) {
                // Swallow the exception
            }
        }
    }
}

