    // Initialization
    GraphPath<V, E> path = new GraphPath<>();

    // Iterate over the edges in the tour
    for (E edge : tour) {
        // Add the edge to the path
        path.addEdge(edge);

        // Add the source and target vertices to the vertex list
        path.addVertex(graph.getEdgeSource(edge));
        path.addVertex(graph.getEdgeTarget(edge));
    }

    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Create a new graph path
    GraphPath<V, E> path = new GraphPath<>(graph);

    // Add the first node
    path.addNode(graph.getFirstNode());

    // Iterate over the edges in the tour
    for (E edge : tour) {
        // Get the nodes adjacent to the edge
        V node1 = graph.getNode1(edge);
        V node2 = graph.getNode2(edge);

        // Add the nodes to the path in order
        path.addNode(node1);
        path.addNode(node2);

        // Add the edge to the path
        path.addEdge(edge);
    }

    // Return the completed path
    return path;
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Create a new graph path with the correct size
    GraphPath<V, E> path = new GraphPath<V, E>(graph, tour.size());

    // Iterate over the edges in the set representation of the tour
    for (E edge : tour) {
        // Get the source and target vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the edge to the graph path
        path.addEdge(edge);

        // Set the source/target vertices in the graph path
        path.setEdgeSource(path.getSize() - 1, source);
        path.setEdgeTarget(path.getSize() - 1, target);
    }

    return path;
}

