    GraphPath<V, E> path = new GraphPathImpl<>(graph);

    // Add the first edge
    E firstEdge = tour.iterator().next();
    path.addEdge(firstEdge);

    // Iterate over the remaining edges
    for (E edge : tour) {
        // Get the endpoints of the edge
        V src = edge.getSource();
        V dst = edge.getDest();

        // Add the edge to the path, unless it is a loop
        if (!src.equals(dst)) {
            path.addEdge(edge);
        }
    }

    return path;
