public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 1; i < constantPool.length; i++) {
        Symbol symbol = constantPool[i];
        if (symbol.getTag() == Symbol.CONSTANT_NameAndType && symbol.getBytes().equals(name.getBytes()) && symbol.getDescriptor().equals(descriptor)) {
            return i;
        }
    }

    // If the constant pool does not contain a similar item, add a new one
    Symbol symbol = new Symbol(Symbol.CONSTANT_NameAndType, name.getBytes(), descriptor, null);
    constantPool.put(symbol);
    return constantPool.size() - 1;
}

int addConstantNameAndType(final String name, final String descriptor) {
    ConstantNameAndTypeInfo existingConstant = getExistingConstantNameAndType(name, descriptor);
    if (existingConstant != null) {
        return existingConstant.index();
    }

    ConstantNameAndTypeInfo newConstant = new ConstantNameAndTypeInfo(name, descriptor);
    constants.add(newConstant);
    return constants.size() - 1;
}

int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPoolSize; i++) {
        ConstantPoolEntry entry = constantPool[i];
        if (entry.name.equals(name) && entry.descriptor.equals(descriptor)) {
            return i;
        }
    }

    // If we reach here, it means we don't have a matching entry in the constant pool, so we need to create one
    ConstantPoolEntry entry = new ConstantPoolEntry(name, descriptor);
    if (constantPoolSize == constantPool.length) {
        // If the constant pool is full, we need to resize it
        ConstantPoolEntry[] newPool = new ConstantPoolEntry[constantPoolSize * 2];
        System.arraycopy(constantPool, 0, newPool, 0, constantPoolSize);
        constantPool = newPool;
    }
    constantPool[constantPoolSize++] = entry;
    return constantPoolSize - 1;
}

public int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new NullPointerException("Name and descriptor must not be null");
    }
    int index = findConstantNameAndType(name, descriptor);
    if (index == -1) {
        index = addConstantInfo(ConstantKind.CONSTANT_NameAndType, new NameAndTypeInfo(name, descriptor));
    }
    return index;
}

public String unescapeId(String input) {
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char current = input.charAt(i);
        if (current == '\\' && i + 1 < input.length()) {
            builder.append(input.charAt(i + 1));
            i++;
        } else {
            builder.append(current);
        }
    }
    return builder.toString();
}

