public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    if (node.next == null) {
        node.prev.next = null;
    } else {
        node.prev.next = node.next;
    }

    node.prev = null;
    node.next = null;
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new NullPointerException("node cannot be null");
    }

    ListNodeImpl<E> previous = node.getPrevious();
    ListNodeImpl<E> next = node.getNext();

    if (previous != null) {
        previous.setNext(next);
    }
    if (next != null) {
        next.setPrevious(previous);
    }

    node.setPrevious(null);
    node.setNext(null);

    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    // Check if the node is null or the head of the list
    if (node == null || node.getNext() == null) {
        return false;
    }

    // Get the previous and next nodes
    ListNodeImpl<E> prev = node.getPrev();
    ListNodeImpl<E> next = node.getNext();

    // Unlink the node from the list
    prev.setNext(next);
    next.setPrev(prev);

    return true;
}

public boolean unlink(ListNodeImpl node) {
    // Check if the node is not null
    if (node == null) {
        return false;
    }

    // Get the previous and next nodes
    ListNodeImpl previous = node.getPrevious();
    ListNodeImpl next = node.getNext();

    // If the node is the first node in the list
    if (previous == null) {
        // Set the first node to the next node
        first = next;
    } else {
        // Set the previous node's next pointer to the next node
        previous.setNext(next);
    }

    // If the node is the last node in the list
    if (next == null) {
        // Set the last node to the previous node
        last = previous;
    } else {
        // Set the next node's previous pointer to the previous node
        next.setPrevious(previous);
    }

    // Reduce the size of the list
    size--;

    // Return true if the node was successfully removed
    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    boolean result = false;
    if (node != null) {
        ListNodeImpl<E> curr = this.head;
        while (curr != null) {
            if (curr.equals(node)) {
                result = true;
                break;
            }
            curr = curr.next;
        }
        if (result) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }
    }
    return result;
}

