public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    // List all current profiles
    List<Profile> profiles = Profile.listAll();
    // Iterate over each profile
    for (Profile profile : profiles) {
        // Get the profile segment snapshot
        SegmentSnapshot segmentSnapshot = profile.getSegmentSnapshot();
        // Get the segment search constraints
        SegmentSearchConstraint searchConstraints = segmentSnapshot.getSegmentSearchConstraints();
        // Get the search parameters
        SearchParameters searchParameters = searchConstraints.getSearchParameters();
        // Get the search sequences
        List<SearchSequence> searchSequences = searchParameters.getSearchSequences();
        // Iterate over each search sequence
        for (SearchSequence searchSequence : searchSequences) {
            // Get the sequence ranges
            List<SequenceRange> sequenceRanges = searchSequence.getSequenceRanges();
            // Add the sequence ranges to the overall list
            sequenceRanges.addAll(sequenceRanges);
        }
    }
    // Return the list of sequence ranges
    return sequenceRanges;
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Add a new SequenceRange instance for the current user profile
    SequenceRange currentProfileRange = new SequenceRange(
        null, // no parent sequence range
        "profile_" + userId, // sequence range name
        null // no range start or end values
    );
    sequenceRanges.add(currentProfileRange);

    // Add a new SequenceRange instance for each profile segment
    for (int i = 0; i < numProfileSegments; i++) {
        SequenceRange segmentRange = new SequenceRange(
            currentProfileRange, // parent sequence range
            "segment_" + i, // sequence range name
            null // no range start or end values
        );
        sequenceRanges.add(segmentRange);
    }

    // Add a new SequenceRange instance for the current snapshot
    SequenceRange snapshotRange = new SequenceRange(
        currentProfileRange, // parent sequence range
        "snapshot", // sequence range name
        null // no range start or end values
    );
    sequenceRanges.add(snapshotRange);

    // Add a new SequenceRange instance for each search query
    for (String query: searchQueries) {
        SequenceRange queryRange = new SequenceRange(
            snapshotRange, // parent sequence range
            "query_" + query, // sequence range name
            null // no range start or end values
        );
        sequenceRanges.add(queryRange);
    }

    return sequenceRanges;
}

private List<SequenceRange> buildSequenceRanges() {
	List<SequenceRange> sequenceRanges = new ArrayList<>();

	// create a SequenceRange for each profile segment
	for (ProfileSegment segment : profileSegments) {
		SequenceRange sequenceRange = new SequenceRange(segment.getId(), segment.getStart(), segment.getEnd());
		sequenceRanges.add(sequenceRange);
	}

	// sort the sequence ranges by start position
	sequenceRanges.sort(Comparator.comparingInt(SequenceRange::getStart));

	return sequenceRanges;
}

