private String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();
    while (true) {
        char c = nextChar();
        if (c == EOF || Arrays.binarySearch(terminators, c) >= 0) {
            break;
        }
        token.append(c);
    }
    return token.toString();
}

private String parseToken(char[] terminators) {
    StringBuilder token = new StringBuilder();

    while (true) {
        if (isTerminator(terminators, peekChar())) {
            break;
        }
        token.append(readChar());
    }

    return token.toString();
}

