public static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // If the input list is empty, return an empty list and 0
    if (bounds.isEmpty()) {
        return new Pair<>(Collections.emptyList(), 0L);
    }

    // Initialize the sum variable to the last element of the input list
    long sum = bounds.get(bounds.size() - 1);

    // Create a new list to store the suffix sum
    List<Integer> suffixSum = new ArrayList<>();

    // Iterate over the list in reverse order
    for (int i = bounds.size() - 2; i >= 0; i--) {
        // Add the current element to the sum
        sum += bounds.get(i);

        // Add the sum to the suffix sum list
        suffixSum.add((int) sum);
    }

    // Return the pair of suffix sum list and the sum of all elements
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0L;
    for (int i = bounds.size() - 1; 0 <= i; --i) {
        sum += bounds.get(i);
        suffixSum.add((int) sum);
    }
    return new Pair<>(suffixSum, sum);
}

