public static final void reverse(V[] arr, int from, int to) {
    // Check if from and to are valid indices in the array
    if (from < 0 || to >= arr.length || from > to) {
        throw new IndexOutOfBoundsException("Invalid indices in the range to reverse");
    }

    // Loop through the range of elements to reverse
    for (int i = from, j = to; i < j; i++, j--) {
        // Swap the elements at i and j with each other
        V tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

