        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

public static final void reverse(V[] arr, int from, int to) {
    if (from < 0 || to >= arr.length || from > to) {
      throw new IllegalArgumentException("Invalid range");
    }
    while (from < to) {
      V temp = arr[from];
      arr[from] = arr[to];
      arr[to] = temp;
      from++;
      to--;
    }
  }

public static final void reverse(V[] arr, int from, int to) {
    int mid = (from + to) / 2;
    for (int i = from, j = to; i < mid; i++, j--) {
        V tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

