public ByteVector putInt(final int intValue) {
    // Enlarge the byte vector if necessary
    if (bytes.length - pos < 4) {
        byte[] newBytes = new byte[bytes.length + 4];
        System.arraycopy(bytes, 0, newBytes, 0, pos);
        bytes = newBytes;
    }

    // Write the int value as 4 bytes into the byte vector
    bytes[pos] = (byte) ((intValue >> 24) & 0xFF);
    bytes[pos + 1] = (byte) ((intValue >> 16) & 0xFF);
    bytes[pos + 2] = (byte) ((intValue >> 8) & 0xFF);
    bytes[pos + 3] = (byte) (intValue & 0xFF);

    // Increment the position
    pos += 4;

    return this;
}

