    ensureCapacity(size() + numBytes);

    // Convert the int value to bytes and store it into the byte vector
    byte[] bytes = new byte[numBytes];
    for (int i = 0; i < numBytes; i++) {
        bytes[i] = (byte) (intValue >> (i * 8));
    }

