public void pop(String descriptor) {
    // Use the same number of pops as the number of arguments of the descriptor
    int argCount = Type.getArgumentTypes(descriptor).length;
    for (int i = 0; i < argCount; i++) {
        outputStack.pop();
    }
}

private void pop(final String descriptor) {
    if (descriptor.startsWith("(")) {
        // method descriptor
        final String methodDescriptor = descriptor;
        final String methodName = methodDescriptor.substring(0, methodDescriptor.indexOf("("));
        final String[] argumentDescriptors = methodDescriptor.substring(methodName.length() + 1, methodDescriptor.length() - 1).split(",");
        for (final String argumentDescriptor : argumentDescriptors) {
            pop(argumentDescriptor);
        }
    } else {
        // type descriptor
        switch (descriptor) {
            case "Z":
                pop(new BooleanValue());
                break;
            case "B":
                pop(new ByteValue());
                break;
            case "C":
                pop(new CharValue());
                break;
            case "S":
                pop(new ShortValue());
                break;
            case "I":
                pop(new IntegerValue());
                break;
            case "J":
                pop(new LongValue());
                break;
            case "F":
                pop(new FloatValue());
                break;
            case "D":
                pop(new DoubleValue());
                break;
            case "Ljava/lang/String;":
                pop(new StringValue());
                break;
            default:
                throw new IllegalStateException("Unsupported type descriptor: " + descriptor);
        }
    }
}

private void pop(String descriptor) {
    if (descriptor.startsWith("(")) { // if descriptor is a method descriptor
        // pop argument types from the output frame stack
        int numArgs = Type.getArgumentTypes(descriptor).length;
        for (int i = 0; i < numArgs; i++) {
            this.outputFrameStack.pop();
        }
    } else { // if descriptor is a type descriptor
        // pop a single type from the output frame stack
        this.outputFrameStack.pop();
    }
}

private void pop(String descriptor) {
    String[] params = descriptor.split(";");
    int numOutputValues = params.length;
    Object[] output = new Object[numOutputValues];
    int curDepth = this.getIndex();
    for (int i = 0; i < numOutputValues; i++) {
        int index = curDepth - 1 - i;
        int code = this.getCode(index);
        String type = params[i];
        if (type.equals("J") || type.equals("D")) {
            // long and double are returned as a pair of ints in the output frame
            int code2 = this.getCode(index - 1);
            output[i] = new Object[] {code, code2};
        } else {
            output[i] = code;
        }
    }
    this.setIndex(curDepth - numOutputValues);
    return output;
}

public void pop(String descriptor) {
    int numArgs = 0;

    // Check if the descriptor is a method descriptor
    if (descriptor.contains("(")) {
        numArgs = descriptor.split("\\(")[1].split("\\)")[0].split(",").length;
    }

    // Pop the appropriate number of abstract types from the output frame stack
    for (int i = 0; i < numArgs; i++) {
        outputFrameStack.pop();
    }
}

