public static String applyRelativePath(String path, String relativePath){
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");
    List<String> resultPathParts = new ArrayList<>();
    int i = 0;
    while (i < pathParts.length && i < relativeParts.length && pathParts[i].equals(relativeParts[i])){
        i++;
    }
    for (; i < pathParts.length; i++){
        resultPathParts.add(pathParts[i]);
    }
    for (; i < relativeParts.length; i++){
        resultPathParts.add(relativeParts[i]);
    }
    return String.join("/", resultPathParts);
}

public static String applyRelativePath(String path, String relativePath) {
    return new File(path).toPath().resolve(relativePath).normalize().toString();
}

public static String applyRelativePath(String path, String relativePath) {
    // First, split the path into its individual parts
    String[] pathParts = path.split("/");
    // Then, split the relative path into its individual parts
    String[] relativePathParts = relativePath.split("/");

    // Create a new list to store the complete path
    List<String> completePath = new ArrayList<>();

    // Loop through the relative path parts and determine which ones need to be added to the complete path
    for (int i = 0; i < relativePathParts.length; i++) {
        // If the current part is "..", remove the previous part from the complete path
        if (relativePathParts[i].equals("..")) {
            if (!completePath.isEmpty()) {
                completePath.remove(completePath.size() - 1);
            }
        } else {
            // Otherwise, add the current part to the complete path
            completePath.add(relativePathParts[i]);
        }
    }

    // Join the complete path parts with "/" separators to form the final path
    String finalPath = String.join("/", completePath);

    // Return the final path
    return finalPath;
}

public static String applyRelativePath(String path,String relativePath){
    // Check if the path is null or empty
    if(path == null || path.isEmpty()){
        throw new IllegalArgumentException("Path cannot be null or empty");
    }

    // Check if the relative path is null or empty
    if(relativePath == null || relativePath.isEmpty()){
        throw new IllegalArgumentException("Relative path cannot be null or empty");
    }

    // Split the path into an array of strings, using the default file separator
    String[] pathParts = path.split(File.separator);

    // Split the relative path into an array of strings, using the default file separator
    String[] relativePathParts = relativePath.split(File.separator);

    // Create a list to store the parts of the new path
    List<String> newPathParts = new ArrayList<>();

    // Iterate over the relative path parts and determine where they should be inserted into the new path
    for(int i = 0; i < relativePathParts.length; i++){
        // If the part is "..", remove the last part of the new path
        if(relativePathParts[i].equals("..")){
            if(newPathParts.size() > 0){
                newPathParts.remove(newPathParts.size() - 1);
            }
        // If the part is not "..", add it to the new path
        } else {
            newPathParts.add(relativePathParts[i]);
        }
    }

    // Iterate over the remaining path parts and add them to the new path
    for(int i = 0; i < pathParts.length; i++){
        if(!newPathParts.contains(pathParts[i])){
            newPathParts.add(pathParts[i]);
        }
    }

    // Join the parts of the new path into a string using the default file separator
    String newPath = String.join(File.separator, newPathParts);

    return newPath;
}

