    int extensionIndex = lastSeparatorIndex + 1;
    int length = filename.length();
    while (extensionIndex < length) {
        if (filename.charAt(extensionIndex) == '.') {
            return extensionIndex;
        }
        extensionIndex++;
    }
    return -1;
}

