public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int separatorIndex = indexOfLastSeparator(filename);
    if (separatorIndex == -1) {
        return -1;
    }
    int extensionIndex = separatorIndex + 1;
    int lastIndex = filename.length() - 1;
    if (extensionIndex <= lastIndex) {
        if (filename.charAt(lastIndex) == '.') {
            if (lastIndex > extensionIndex) {
                return extensionIndex;
            } else {
                return -1;
            }
        } else {
            return -1;
        }
    }

    return extensionIndex;
}

