Edge edgeToNext() {
    // Check if either of the nodes is virtual
    if (node.isVirtual()) {
        // If the current node is virtual, find its real counterpart and return an edge between them
        return new Edge(node.getRealNode(), node.getNextNode());
    } else if (node.getNextNode().isVirtual()) {
        // If the next node is virtual, find its real counterpart and return an edge between them
        return new Edge(node, node.getNextNode().getRealNode());
    } else {
        // If both nodes are real, just return an edge between them
        return new Edge(node, node.getNextNode());
    }
}

