    if (isVirtual(getCurrentNode()) || isVirtual(getNextNode())) {
        Node realCurrentNode = getRealNode(getCurrentNode());
        Node realNextNode = getRealNode(getNextNode());
        return realCurrentNode.connectsTo(realNextNode);
    } else {
        return getCurrentNode().connectsTo(getNextNode());
    }
}

