    Node currentNode = getCurrentNode();

    // Get the next node
    Node nextNode = getNextNode();

    // Check if either of the nodes is virtual
    if (currentNode.isVirtual() || nextNode.isVirtual()) {
        // If either of the nodes is virtual, get the real counterpart
        currentNode = currentNode.getRealNode();
        nextNode = nextNode.getRealNode();
    }

    // Return an edge connecting the current node to the next node
    return new Edge(currentNode, nextNode);
}

