public int readTag() throws IOException {
    if (data.getPosition() >= this.data.getLength()) {
        return 0;
    }

    int tag = data.readUnsignedByte();
    if (tag < 0x80) {
        return tag;
    } else {
        // Check for a continuation byte
        if ((tag & 0x40) == 0x40) {
            // Read the next byte
            int nextByte = data.readUnsignedByte();
            // Make sure the continuation byte is not a one-byte tag number
            if (nextByte < 0x80) {
                throw new IOException("Protocol message contained a malformed tag.");
            }
            // Shift the tag and the continuation byte, and return the result
            return (tag << 7) | (nextByte & 0x7F);
        } else {
            // Check for an extension byte
            if ((tag & 0x20) == 0x20) {
                // Read the extension type
                int extType = 0;
                if ((tag & 0x10) == 0x10) {
                    extType = data.readUTF();
                } else {
                    extType = data.readInt();
                }
                // Return a malformed tag exception
                throw new IOException("Protocol message contained an extension with an invalid type.");
            }
        }
    }
    return tag;
}

