public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        if (line.startsWith("ThreadSnapshot")) {
            String[] parts = line.split("\\s+");
            long threadId = Long.parseLong(parts[1]);
            long totalDuration = Long.parseLong(parts[2]);
            List<ProfileAnalyzeEvent> events = new ArrayList<>();
            while ((line = reader.readLine()) != null && !line.startsWith("ThreadSnapshot")) {
                String[] eventParts = line.split("\\s+");
                events.add(new ProfileAnalyzeEvent(Long.parseLong(eventParts[0]), eventParts[1], Long.parseLong(eventParts[2]), Long.parseLong(eventParts[3])));
            }
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timeRange.inRange(totalDuration)) {
                    threadSnapshots.add(new ThreadSnapshot(threadId, totalDuration, events, timeRange));
                }
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // ignore comment lines
            if (!line.startsWith("#")) {
                String[] tokens = line.split(" ");
                if (tokens.length >= 5) {
                    long timestamp = Long.parseLong(tokens[0]);
                    // check if timestamp falls within the specified time range
                    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                        if (timestamp >= timeRange.getStart() && timestamp <= timeRange.getEnd()) {
                            // create a new ThreadSnapshot object with the required parameters
                            ThreadSnapshot snapshot = new ThreadSnapshot();
                            snapshot.setTimestamp(timestamp);
                            snapshot.setName(tokens[4]);
                            snapshot.setThreadId(Long.parseLong(tokens[2]));
                            snapshot.setIsDaemon(Boolean.parseBoolean(tokens[3]));
                            snapshots.add(snapshot);
                            break;
                        }
                    }
                }
            }
        }
    }

    return snapshots;
}
